mapper.select:
SELECT COUNT(*) FROM BOARD_POST bp INNER JOIN BOARD_CATEGORY bc ON bp.SEQCATEGORY = bc.SEQCATEGORY INNER JOIN MEMBER m ON bp.SEQMEMBER = m.SEQMEMBER WHERE bp.STATUS = 'NORMAL'
AND bc.CATEGORYNAME = #{category}
AND ( bp.TITLE LIKE '%' || #{searchWord} || '%' OR REGEXP_REPLACE(bp.CONTENT, '<[^>]+>', '') LIKE '%' || #{searchWord} || '%' )

SELECT * FROM ( SELECT ROW_NUMBER() OVER (ORDER BY bp.SEQBOARDPOST DESC) AS rnum, bp.SEQBOARDPOST AS seqBoardPost, bp.SEQCATEGORY AS seqCategory, bp.SEQMEMBER AS seqMember, bp.TITLE AS title, bp.CONTENT AS content, bp.VIEWCOUNT AS viewCount, bp.STATUS AS status, TO_CHAR(bp.CREATEDATE, 'YYYY-MM-DD') AS createDate, TO_CHAR(bp.UPDATEDATE, 'YYYY-MM-DD') AS updateDate, bc.CATEGORYNAME AS categoryName, m.NAME AS writerName, f.SAVEDNAME AS savedName FROM BOARD_POST bp INNER JOIN BOARD_CATEGORY bc ON bp.SEQCATEGORY = bc.SEQCATEGORY INNER JOIN MEMBER m ON bp.SEQMEMBER = m.SEQMEMBER LEFT JOIN ( SELECT SEQBOARDPOST, SAVEDNAME, ROW_NUMBER() OVER ( PARTITION BY SEQBOARDPOST ORDER BY SEQBOARDPOSTFILE ASC ) AS file_rnum FROM BOARD_POST_FILE ) f ON bp.SEQBOARDPOST = f.SEQBOARDPOST AND f.file_rnum = 1 WHERE bp.STATUS = 'NORMAL'
AND bc.CATEGORYNAME = #{category}
AND ( bp.TITLE LIKE '%' || #{searchWord} || '%' OR REGEXP_REPLACE(bp.CONTENT, '<[^>]+>', '') LIKE '%' || #{searchWord} || '%' )
) WHERE rnum BETWEEN #{begin} AND #{end}

mapper.update:
UPDATE BOARD_POST
SET VIEWCOUNT = VIEWCOUNT + 1
WHERE SEQBOARDPOST = #{seqBoardPost}

mapper.select:
SELECT SEQMEMBER
FROM BOARD_POST
WHERE SEQBOARDPOST = #{seqBoardPost}
